import { mountScene } from './scene.js';

const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = name => `<svg class="icon" aria-hidden="true"><use href="#i-${esc(name)}"/></svg>`;
const STATUS = {queued:'排队中',running:'执行中',awaiting_approval:'等待你的审批',completed:'已交付',failed:'执行失败',cancelled:'已取消',pending:'等待上游证据',done:'已完成',error:'失败',idle:'待命',working:'执行中'};
const TYPE = {task:'任务',model:'模型调用',tool:'工具调用',result:'执行结果',handoff:'证据交接',approval:'真人审批',error:'错误',artifact:'文件产物'};
const TOOLS = {import_finance:'导入财务底稿',calculate_finance:'计算财务指标',audit_finance:'独立财务审校',search_web:'互联网搜索',fetch_quote:'抓取报价证据',compare_quotes:'核对报价与配置',inspect_network:'读取网络日志',analyze_traffic:'分析异常流量',apply_defense:'审批并应用防护',verify_network:'独立验证业务流量',design_database:'设计表结构与 SQL',build_database:'真实创建 SQLite',test_database:'执行数据库测试',extract_requirements:'提取需求与验收项',estimate_delivery:'核算工期和预算',review_delivery:'审校交付一致性',write_report:'生成正式报告',list_artifacts:'读取交接产物'};
const NODE_SCENARIO={finance:'finance',server:'procurement',firewall:'ddos',internet:'ddos',core:'ddos',storage:'database',reception:'delivery',meeting:'delivery',workstations:'delivery',executive:'finance'};
const NODE_NAMES={finance:'财务工作台',server:'服务器采购',firewall:'安全网关',internet:'互联网',core:'网络控制台',storage:'数据库与存储',reception:'业务接待区',meeting:'会议室',workstations:'员工工位',executive:'管理工作台',access:'接入交换机',ups:'UPS 电源'};
const TERMINAL=new Set(['completed','failed','cancelled']);
const CONFIG_KEY='real-ai-office-config-v1';
let catalog={agents:[],scenarios:[]},health={provider:{ready:false,message:'检查模型连接中'}},runs=[],run=null;
let panel=null,stream=null,reconnectTimer=null,connectionState='idle',busy=false,topology=true;
let configs={},drafts={},inputSource={},panelSignature='',lastApprovalId=null,toastTimer;
const seenEvents=new Set(),notices=new Map(),noticeQueue=[];
const $scene=$('#office-scene'),$panel=$('#scene-popover'),$content=$('#popover-content');
const noticeLayer=document.createElement('div');noticeLayer.id='notice-layer';$('#lab').append(noticeLayer);
const scene=mountScene($scene,{onSelectNode:id=>openPanel('node',id),onSelectAgent:id=>openPanel('agent',id,'work'),onViewChange:()=>positionOverlays()});
const agent=id=>catalog.agents.find(a=>a.id===id)||{id,name:'系统',role:'协作调度',color:'#7a998a',tools:[]};
const scenario=id=>catalog.scenarios.find(s=>s.id===id);
const config=id=>configs[id]||agent(id);
const alive=()=>run&&!TERMINAL.has(run.status);
const fmtTime=seconds=>{const n=Math.max(0,Math.floor(Number(seconds)||0));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;};
const date=value=>value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—';
const bytes=value=>value>1048576?`${(value/1048576).toFixed(1)} MB`:`${Math.max(1,Math.round(value/1024))} KB`;
const short=(value,max=260)=>String(value??'').length>max?`${String(value).slice(0,max)}…`:String(value??'');
function portrait(id){if(!id||id==='human')return `<span class="system-avatar ${id==='human'?'human':''}">${icon(id==='human'?'users':'network')}</span>`;const a=agent(id);return `<span class="ai-avatar" style="--avatar:${esc(a.color)}">${esc(a.name.slice(0,1))}<b>AI</b></span>`;}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>{$('#toast').hidden=true;},4000);}
async function api(path,method='GET',body){const response=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store'});let data;try{data=await response.json();}catch{throw new Error('服务未返回有效数据，请检查办公室服务。');}if(!response.ok)throw new Error(typeof data.error==='string'?data.error:data.error?.message||data.message||`请求失败（${response.status}）`);return data;}
function safeUrl(value){try{const u=new URL(String(value),location.origin);return /^https?:$/.test(u.protocol)?u.href:null;}catch{return null;}}
function artifactUrl(artifact){const u=safeUrl(artifact.url);return u&&new URL(u).origin===location.origin?u:null;}
function header(title,eyebrow=''){return `<div class="popover-inner">${eyebrow?`<div class="popover-eyebrow">${esc(eyebrow)}</div>`:''}<div class="popover-top"><h2>${esc(title)}</h2><button class="icon-button" data-close aria-label="关闭操作面板">${icon('close')}</button></div>`;}
function openPanel(type,id=null,tab=null){if(panel?.type==='task')captureTaskForm();panel={type,id,tab};panelSignature='';scene.setSelectedAgent(type==='agent'?id:null);scene.setSelectedNode(type==='node'?id:null);if(type==='agent'){const p=scene.getAgentAnchor(id),r=$scene.getBoundingClientRect();if(p&&(p.x+r.left<40||p.x+r.left>innerWidth-40))scene.focusAgent(id);}renderPanel(true);renderDock();renderNotices();}
function closePanel(){if(panel?.type==='task')captureTaskForm();panel=null;panelSignature='';$panel.hidden=true;scene.setSelectedAgent(null);scene.setSelectedNode(null);renderDock();renderNotices();}
function errorBox(text){return `<div class="office-error" role="alert">${icon('info')}<span>${esc(text)}</span></div>`;}
function empty(text){return `<div class="office-empty">${esc(text)}</div>`;}
function resultText(value){if(typeof value==='string')return value;return value==null?'':JSON.stringify(value,null,2);}
function evidenceMarkup(data,key='',label='查看返回证据'){if(!data)return '';const text=typeof data==='string'?data:JSON.stringify(data,null,2);const links=[];const walk=(v,depth=0)=>{if(depth>5||links.length>12)return;if(typeof v==='string'&&/^https?:\/\//.test(v)){const u=safeUrl(v);if(u&&!links.includes(u))links.push(u);}else if(Array.isArray(v))v.slice(0,15).forEach(x=>walk(x,depth+1));else if(v&&typeof v==='object')Object.values(v).slice(0,30).forEach(x=>walk(x,depth+1));};walk(data);return `<details class="evidence" data-evidence-key="${esc(key)}"><summary>${esc(label)}</summary>${links.map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(short(u,100))}${icon('arrow')}</a>`).join('')}<pre>${esc(short(text,12000))}</pre></details>`;}
function logMarkup(event){return `<article class="office-log ${esc(event.type)}"><div class="office-log-top">${portrait(event.actor==='human'?'human':event.agentId)}<strong>${esc(event.actor==='human'?'你 · 真人负责人':agent(event.agentId).name)}${event.targetAgentId?` → ${esc(agent(event.targetAgentId).name)}`:''}</strong><span class="event-type">${esc(TYPE[event.type]||event.type)}</span><time>${event.createdAt?new Date(event.createdAt).toLocaleTimeString('zh-CN',{hour12:false}):fmtTime(event.time)}</time></div><p>${esc(event.text)}</p>${event.tool?`<span class="tool-tag">${esc(TOOLS[event.tool]||event.tool)}</span>`:''}${evidenceMarkup(event.data??event.args,event.id,event.data?'查看返回证据':'查看调用参数')}</article>`;}
function artifactMarkup(file){const url=artifactUrl(file);return `<div class="office-artifact">${icon(file.mimeType?.includes('sqlite')?'layers':'book')}<span><strong>${esc(file.name)}</strong><small>${esc(file.mimeType||'文件')} · ${bytes(file.bytes||0)}</small></span>${url?`<a class="button" href="${esc(url)}" download>${icon('download')}下载</a>`:'<span>链接不可用</span>'}</div>`;}
function agentChip(id){return `<button type="button" class="person-link" data-agent="${esc(id)}">${portrait(id)}${esc(agent(id).name)}<b class="ai-tag">AI</b></button>`;}
function renderHud(){const provider=health.provider||{};$('#online-count').textContent=provider.ready?'模型已连接':'模型未连接';$('#availability').textContent=provider.model||provider.provider||'Codex';$('#network-hud .status-dot').className=`status-dot ${provider.ready?'':'warning'}`;$('#squad-label').textContent=`${catalog.agents.length||7} 位 AI 员工 · 点人配置`;
const hud=$('#incident-hud');hud.hidden=!run;if(run){const done=run.tasks.filter(t=>t.status==='done').length,total=run.tasks.length;hud.className=`incident-hud glass ${run.status==='completed'?'completed':''} ${run.status==='failed'?'degraded':''}`;hud.innerHTML=`<button class="incident-open" data-open="progress"><div class="incident-heading">${icon(run.status==='completed'?'check':run.status==='failed'?'info':'activity')}<span>${esc(run.title)}</span><time>${fmtTime(run.elapsedSeconds)}</time></div><div class="incident-sub"><strong>${esc(STATUS[run.status])}</strong><span>${done}/${total} 项任务</span><span>${connectionState==='reconnecting'?'连接中断，正在重连':alive()?'实时同步':''}</span></div></button>`;}
$('#scene-cue').hidden=!!run||!!panel;}
function renderDock(){let primary=alive()?`<button class="dock-action dock-primary" data-open="${run.approval?'approval':'progress'}">${icon(run.approval?'check':'activity')}<span>${run.approval?'审批任务':'查看进展'}</span></button>`:`<button class="dock-action dock-primary" data-open="tasks">${icon('play')}<span>派发任务</span></button>`;$('#action-dock').innerHTML=`<button class="dock-action" data-open="employees">${icon('users')}<span>员工</span></button><button class="dock-action" data-open="logs">${icon('terminal')}<span>记录</span></button><span class="dock-divider"></span>${primary}<button class="dock-action" data-open="artifacts">${icon('download')}<span>产物${run?.artifacts?.length?` ${run.artifacts.length}`:''}</span></button><button class="dock-action dock-more" data-open="more" aria-label="更多操作">${icon('grid')}</button>`;}
function renderTasks(){return `${header('派发办公任务','选择任务 → 提供资料 → AI 员工协作')}<div class="office-scenarios">${catalog.scenarios.map(s=>`<button class="office-scenario" data-scenario="${esc(s.id)}"><span class="scenario-symbol">${icon(s.icon||'book')}</span><span><strong>${esc(s.title)}</strong><small>${esc(s.description)}</small><em>${esc(s.outputs.join(' · '))}</em></span>${icon('chevron')}</button>`).join('')}</div>${alive()?'<div class="office-note">当前已有任务执行，结束或取消后可派发新任务。</div>':''}</div>`;}
function taskDraft(id){if(!drafts[id])drafts[id]=Object.fromEntries((scenario(id)?.fields||[]).filter(f=>f.type!=='file').map(f=>[f.name,f.defaultValue??'']));return drafts[id];}
function setInputSource(id,source){inputSource[id]=source;const d=taskDraft(id),isExample=source==='example';d.example=isExample;d.isExample=isExample;}
function financeFormat(){return `<div class="finance-format"><button type="button" class="button" data-finance-template>${icon('download')}下载示例模板</button><details class="workflow-preview"><summary>数据格式 · 11 列月度数据</summary><p>金额单位：元。汇报年与上一年各 12 个月，月末现金与下月期初现金衔接。</p><dl>${[['year','年度'],['month','月份'],['revenue','营业收入'],['cost','营业成本'],['operating_expense','经营费用'],['other_income','其他收益'],['tax','税费'],['opening_cash','期初现金'],['cash_in','现金流入'],['cash_out','现金流出'],['closing_cash','期末现金']].map(([name,label])=>`<div><dt>${name}</dt><dd>${label}</dd></div>`).join('')}</dl><p>用于经营与现金收支汇报，不替代法定财务三表。</p></details></div>`;}
async function downloadFinanceTemplate(){const data=await api('/api/examples/finance'),csv=data.input?.data?.text;if(typeof csv!=='string'||!csv.trim())throw new Error('示例模板暂不可用，请稍后重试。');const blob=new Blob(['\uFEFF',csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='明确示例_年度财务月度数据模板.csv';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('示例模板已下载，请替换为你的月度数据后上传。');}
function fieldMarkup(field,value){const attrs=`name="${esc(field.name)}" ${field.required&&!(field.type==='file'&&value)?'required':''}`;let control;if(field.type==='textarea')control=`<textarea class="field-input" ${attrs} rows="${field.name==='requirements'?4:3}" placeholder="${esc(field.placeholder||'')}">${esc(value??'')}</textarea>`;else if(field.type==='select')control=`<select class="field-input" ${attrs}>${(field.options||[]).map(o=>{const v=typeof o==='object'?o.value:o,label=typeof o==='object'?o.label:o;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(label)}</option>`;}).join('')}</select>`;else if(field.type==='file')control=`<div class="file-upload"><input ${attrs} type="file" accept=".csv,.json,.txt,.xlsx" aria-label="${esc(field.label)}" ${value?'data-has-file="true"':''}><div class="file-value" data-file-value="${esc(field.name)}">${value?`${icon('check')}<span>${esc(value.name||'已载入示例资料')}</span><button type="button" class="button button-text" data-clear-file="${esc(field.name)}">移除</button>`:`${icon('download')}<span>${esc(field.placeholder||'上传 CSV / JSON / TXT / XLSX')}</span>`}</div></div>`;else control=`<input class="field-input" type="${field.type==='number'?'number':'text'}" ${attrs} value="${esc(value??'')}" placeholder="${esc(field.placeholder||'')}" ${field.type==='number'?'step="any"':''}>`;return `<label class="office-field"><span class="field-label">${esc(field.label)}${field.required?'<i>必填</i>':''}</span>${control}</label>`;}
function renderTask(){const s=scenario(panel.id);if(!s)return empty('任务目录未加载');const d=taskDraft(s.id),source=inputSource[s.id];return `${header(s.title,s.room)}<form id="task-form" data-scenario-id="${esc(s.id)}"><div class="input-source ${source==='example'?'example':''}"><span>${source==='example'?`已载入示例：${esc(s.exampleLabel)}`:'使用你提供的资料与需求'}</span><button type="button" class="button" data-example="${esc(s.id)}">${icon('book')}使用示例</button></div><div class="config-form">${s.fields.map(f=>fieldMarkup(f,d[f.name])+(s.id==='finance'&&f.name==='data'?financeFormat():'')).join('')}</div><div class="office-section-label">执行小队 · ${s.agents.length} 位 AI 员工</div><div class="related-agents">${s.agents.map(agentChip).join('')}</div><details class="workflow-preview"><summary>查看分工与交接</summary>${s.tasks.map(t=>`<div><span>${esc(agent(t.agentId).name)}</span><strong>${esc(t.title)}</strong><small>${t.dependencies.length?`等待 ${t.dependencies.map(id=>s.tasks.find(x=>x.id===id)?.title||id).map(esc).join('、')}`:'收到资料即可开始'}</small></div>`).join('')}</details><div id="task-error" hidden></div>${!health.provider?.ready?errorBox('模型尚未连接，先检查连接后再派工。'):''}<div class="form-actions"><button type="button" class="button" data-open="tasks">更换任务</button><button type="submit" class="button button-primary" ${busy||alive()||!health.provider?.ready?'disabled':''}>${icon('play')}${busy?'正在创建任务':'确认资料，一键派工'}</button></div></form></div>`;}
function renderEmployees(){return `${header('AI 虚拟员工','青绿 AI 胸牌 · 每人独立职责与工具权限')}<div class="office-employees">${catalog.agents.map(a=>`<button class="office-employee" data-agent="${esc(a.id)}">${portrait(a.id)}<span><strong>${esc(a.name)} <b class="ai-tag">AI</b></strong><small>${esc(a.role)}</small><em>${config(a.id).tools.map(t=>TOOLS[t]||t).map(esc).join(' · ')}</em></span>${icon('chevron')}</button>`).join('')}</div><div class="human-identity">${icon('users')}<span><strong>你 · 真人负责人</strong><small>审核真实资料，批准变更，决定采购与业务交付。</small></span></div></div>`;}
function renderAgent(){const a=agent(panel.id),c=config(a.id),current=run?.agents.find(x=>x.id===a.id),tasks=run?.tasks.filter(t=>t.agentId===a.id)||[],events=run?.events.filter(e=>e.agentId===a.id||e.targetAgentId===a.id)||[],tab=panel.tab||'work';let html=`${header(`${a.name} · ${a.role}`,'AI 虚拟员工 / 独立上下文 / 受控工具')}<div class="popover-tabs"><button class="popover-tab ${tab==='work'?'active':''}" data-agent-tab="work">任务与行动</button><button class="popover-tab ${tab==='config'?'active':''}" data-agent-tab="config">配置员工</button><button class="popover-tab ${tab==='handoff'?'active':''}" data-agent-tab="handoff">证据交接</button></div>`;if(tab==='config'){html+=`<form id="agent-form" data-agent-id="${esc(a.id)}"><label class="office-field"><span class="field-label">职责指令</span><textarea class="field-input" name="instructions" rows="6" maxlength="1800" required ${alive()?'disabled':''}>${esc(c.instructions)}</textarea></label><div class="office-section-label">允许调用的工具</div><div class="tool-options">${a.tools.map(t=>`<label class="tool-option"><input type="checkbox" name="tools" value="${esc(t)}" ${c.tools.includes(t)?'checked':''} ${alive()?'disabled':''}><span><strong>${esc(TOOLS[t]||t)}</strong><small>${esc(t)}</small></span></label>`).join('')}</div><div class="office-note">${alive()?'本次执行已锁定配置。任务结束后可修改，下次派工生效。':'职责会发给真实模型；工具权限由服务端校验。'}</div><div id="agent-error" hidden></div><div class="form-actions"><button class="button button-primary" type="submit" ${alive()?'disabled':''}>${icon('check')}保存员工配置</button></div></form>`;}else if(tab==='handoff'){const handoffs=events.filter(e=>e.type==='handoff');html+=handoffs.length?handoffs.map(logMarkup).join(''):empty('完成上游任务后，证据会交给依赖该结果的同事。');}else{html+=`<div class="skill-tags">${c.tools.map(t=>`<span class="skill-tag">${esc(TOOLS[t]||t)}</span>`).join('')}</div><div class="agent-work"><div class="work-label">任务</div><p class="work-text strong">${esc(current?.task||c.instructions)}</p></div><div class="agent-work"><div class="work-label">行动</div><p class="work-text">${esc(current?.action||'等待派工')}</p></div><div class="agent-work"><div class="work-label">结果</div><p class="work-result">${esc(short(resultText(current?.result)||'尚未产出本次任务结果',1600))}</p></div>${tasks.length?`<div class="office-section-label">负责的任务</div>${tasks.map(taskMarkup).join('')}`:''}<div class="button-row"><button class="button" data-agent-tab="config">${icon('wrench')}修改职责与工具</button></div>`;}return html+'</div>';}
function taskMarkup(task){return `<article class="office-task ${esc(task.status)}"><div><b>${esc(task.title)}</b><span>${esc(STATUS[task.status]||task.status)}</span></div><small>${esc(agent(task.agentId).name)} · AI${task.dependencies?.length?` · ${task.dependencies.length} 项上游依赖`:''}</small>${task.action?`<p><em>行动</em>${esc(short(task.action,500))}</p>`:''}${task.result?`<p><em>结果</em>${esc(short(resultText(task.result),900))}</p>`:''}${task.output?`<details class="evidence" data-evidence-key="task-${esc(task.id)}"><summary>查看员工交付</summary><pre>${esc(short(resultText(task.output),14000))}</pre></details>`:''}</article>`;}
function renderProgress(){if(!run)return `${header('任务进展')}${empty('派发任务后，实际执行进度会显示在这里。')}</div>`;const models=run.events.filter(e=>e.type==='model'&&e.step).length,tools=run.tasks.reduce((sum,t)=>sum+(Number(t.toolCalls)||0),0);return `${header(run.title,`${STATUS[run.status]} · ${run.model||run.provider||'真实模型'}`)}<div class="office-run-stats"><span><b>${run.tasks.filter(t=>t.status==='done').length}/${run.tasks.length}</b><small>已交付任务</small></span><span><b>${models}</b><small>模型决策</small></span><span><b>${tools}</b><small>工具调用</small></span><span><b>${fmtTime(run.elapsedSeconds)}</b><small>实际执行耗时</small></span></div>${run.error?errorBox(typeof run.error==='string'?run.error:run.error.message||JSON.stringify(run.error)):''}${run.summary?`<div class="office-summary">${esc(resultText(run.summary))}</div>`:''}${run.tasks.map(taskMarkup).join('')}<div class="button-row">${run.approval?`<button class="button button-primary" data-open="approval">需要你的审批</button>`:''}${TERMINAL.has(run.status)?`<button class="button" data-action="retry">${icon('reset')}重新执行</button><button class="button button-primary" data-open="artifacts">${icon('download')}查看实际产物</button>`:`<button class="button button-danger" data-action="cancel">取消任务</button>`}</div></div>`;}
function renderLogs(){const events=run?.events||[];return `${header('协作记录',run?`${run.title} · ${events.length} 条实际事件`:'模型、工具、交接与审批')}<div class="office-log-list">${events.length?events.slice().reverse().map(logMarkup).join(''):empty('尚无执行记录。')}</div></div>`;}
function renderArtifacts(){const files=run?.artifacts||[];return `${header('任务产物',run?`${run.title} · ${STATUS[run.status]}`:'下载实际生成的文件')}${files.length?files.map(artifactMarkup).join(''):empty(alive()?'员工执行后会在此交付文件。':'尚无文件产物。')} ${run?.status==='failed'?errorBox('任务执行失败，已经生成的证据保留在这里，可重试。'):''}${run?`<div class="button-row"><button class="button" data-open="progress">查看任务与验收</button></div>`:''}</div>`;}
function renderApproval(){const a=run?.approval;if(!a)return `${header('真人审批')}${empty('当前没有待审批事项。')}</div>`;return `${header(a.title,'你 · 真人负责人')}<div class="approval-copy">${esc(a.description)}</div>${evidenceMarkup(a.details,a.id,'查看审批方案与证据')}<label class="office-field"><span class="field-label">审批备注（可选）</span><textarea class="field-input" id="approval-note" rows="2" placeholder="填写调整要求或审批依据"></textarea></label><div class="human-identity">${icon('shield')}<span><strong>批准后才执行</strong><small>AI 员工不能替你批准。拒绝会保留方案与证据。</small></span></div><div id="approval-error" hidden></div><div class="button-row"><button class="button" data-approval="false" ${busy?'disabled':''}>拒绝</button><button class="button button-primary" data-approval="true" ${busy?'disabled':''}>${icon('check')}批准执行</button></div></div>`;}
function renderConnection(){const p=health.provider||{};return `${header('模型连接','办公室服务端运行 · 凭证仅保存在服务端')}<div class="provider-status ${p.ready?'ready':''}">${icon(p.ready?'check':'info')}<span><strong>${p.ready?'已连接真实模型':'模型未连接'}</strong><small>${esc(p.provider||'Codex')} · ${esc(p.model||'等待检测')}</small></span></div><p class="office-note">${esc(p.message||'检查本机模型登录状态。')}</p>${p.ready?'':'<p class="office-note">优先使用办公室主机已登录的 Codex；也可在服务端配置 OpenAI 或 Ollama。连接成功前不能派工。</p>'}<div id="connection-error" hidden></div><div class="button-row"><button class="button button-primary" data-action="check-provider" ${busy?'disabled':''}>${icon('reset')}${busy?'正在检查':'重新检查连接'}</button></div><div class="office-section-label">执行边界</div><div class="office-note">财务使用你提供的数据；采购从实时网页保留报价证据；DDoS 在隔离请求副本验证；数据库在任务工作区真实创建；对外采购、付款与发布由你决定。</div></div>`;}
function renderHistory(){return `${header('任务历史','输入、证据与产物保存在办公室主机')}<div class="office-history">${runs.length?runs.map(r=>`<button class="history-row" data-run="${esc(r.id)}"><span><strong>${esc(r.title)}</strong><small>${date(r.createdAt)} · ${r.artifacts?.length||0} 个文件</small></span><em class="status-${esc(r.status)}">${esc(STATUS[r.status])}</em>${icon('chevron')}</button>`).join(''):empty('尚无历史任务。')}</div></div>`;}
function renderNode(){const id=panel.id,s=scenario(NODE_SCENARIO[id]);const events=run?.events.filter(e=>run.tasks.find(t=>t.id===e.taskId)?.nodeId===id)||[];return `${header(NODE_NAMES[id]||id,'工作区动作')}${s?`<button class="context-action" data-scenario="${esc(s.id)}">${icon(s.icon)}<span>${esc(s.title)}<small>${esc(s.outputs.join(' · '))}</small></span>${icon('chevron')}</button>`:''}<div class="office-section-label">本次工作记录 · ${events.length}</div>${events.length?events.slice(-5).reverse().map(logMarkup).join(''):empty('该工作区尚未执行任务。')}<button class="button" data-open="tasks">查看全部办公任务</button></div>`;}
function renderMore(){return `${header('办公动作')}<div class="more-actions"><button class="button" data-open="history">${icon('clock')}任务历史</button><button class="button" data-open="connection">${icon('activity')}模型连接</button><button class="button" data-open="progress">${icon('layers')}任务分工</button><button class="button" data-action="refresh">${icon('reset')}刷新状态</button>${alive()?`<button class="button button-danger" data-action="cancel">${icon('close')}取消当前任务</button>`:''}</div><div class="human-identity">${icon('users')}<span><strong>真人负责人：你</strong><small>青绿 AI 员工执行分析与工具；审批和业务决策由你完成。</small></span></div></div>`;}
function renderPanel(force=false){if(!panel)return;const frozen=panel.type==='task'||panel.type==='agent'&&panel.tab==='config'||panel.type==='approval';const sig=JSON.stringify([panel,frozen?'':run?.updatedAt,health.provider?.ready,health.provider?.message,busy,runs.length]);if(!force&&sig===panelSignature)return;panelSignature=sig;const scroll=$panel.scrollTop,opened=new Set([...$panel.querySelectorAll('details[data-evidence-key][open]')].map(d=>d.dataset.evidenceKey));const renderers={tasks:renderTasks,task:renderTask,employees:renderEmployees,agent:renderAgent,progress:renderProgress,logs:renderLogs,artifacts:renderArtifacts,approval:renderApproval,connection:renderConnection,history:renderHistory,node:renderNode,more:renderMore};$content.innerHTML=(renderers[panel.type]||renderTasks)();$panel.hidden=false;$panel.className=`scene-popover glass office-panel ${['task','progress','logs','artifacts','history'].includes(panel.type)?'wide':''} ${panel.type==='approval'?'approval':''}`;$panel.querySelectorAll('details[data-evidence-key]').forEach(d=>{if(opened.has(d.dataset.evidenceKey))d.open=true;});$panel.scrollTop=scroll;positionOverlays();}
function updateScene(){const agents=run?.agents?.length?run.agents:catalog.agents.map(a=>({...a,configured:true,selected:true,status:'idle'}));scene.update({nodes:run?.nodes||{},agents,logs:run?.events||[]});}
function render(){renderHud();renderDock();renderPanel();updateScene();renderNotices();}
function positionOverlays(){if(!$('#lab'))return;const bounds=$('#lab').getBoundingClientRect(),origin=$scene.getBoundingClientRect(),w=bounds.width,h=bounds.height;if(panel&&!$panel.hidden){const b=$panel.getBoundingClientRect(),anchor=panel.type==='agent'?scene.getAgentAnchor(panel.id):panel.type==='node'?scene.getNodeAnchor(panel.id):null;let left=(w-b.width)/2,top=(h-b.height)/2-8;if(anchor&&w>850){const x=anchor.x+origin.left-bounds.left,y=anchor.y+origin.top-bounds.top;left=x+40+b.width<w-16?x+40:x-b.width-40;top=y-100;}$panel.style.left=`${Math.max(12,Math.min(w-b.width-12,left))}px`;$panel.style.top=`${Math.max(12,Math.min(h-b.height-88,top))}px`;}
const occupied=[];for(const [id]of notices){const el=noticeLayer.querySelector(`[data-notice="${id}"]`),p=scene.getAgentAnchor(id);if(!el||!p)continue;const ew=el.offsetWidth,eh=el.offsetHeight;let x=Math.max(12,Math.min(w-ew-12,p.x+origin.left-bounds.left-ew/2)),y=Math.max(104,Math.min(h-eh-94,p.y+origin.top-bounds.top-eh-35));for(const b of occupied)if(x<b.x+b.w+8&&x+ew>b.x-8&&y<b.y+b.h+8&&y+eh>b.y-8){y=Math.min(h-eh-94,b.y+b.h+10);if(y<b.y+b.h&&w>650)x=Math.max(12,Math.min(w-ew-12,b.x+ew+12));}el.style.left=`${x}px`;el.style.top=`${y}px`;occupied.push({x,y,w:ew,h:eh});}}
function receive(next,{initial=false}={}){if(!next)return;const changed=run?.id!==next.id;if(changed){seenEvents.clear();notices.clear();noticeQueue.splice(0);lastApprovalId=null;}run=next;runs=[next,...runs.filter(r=>r.id!==next.id)].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));for(const e of next.events||[]){if(seenEvents.has(e.id))continue;seenEvents.add(e.id);if(!initial&&e.type==='result'&&e.agentId){const task=next.tasks.find(t=>t.id===e.taskId);noticeQueue.push({id:e.id,agentId:e.agentId,task:task?.title||agent(e.agentId).role,action:task?.action||e.tool&&TOOLS[e.tool]||'已执行工具与分析',result:e.text||resultText(task?.result),remaining:10000});}}
if(next.approval&&next.approval.id!==lastApprovalId){lastApprovalId=next.approval.id;openPanel('approval');}if(TERMINAL.has(next.status)){stream?.close();stream=null;clearTimeout(reconnectTimer);connectionState='closed';if(changed||!initial)toast(next.status==='completed'?'任务已交付，可在「产物」下载文件':next.status==='failed'?'任务失败，证据已保留，可查看原因后重试':'任务已取消');}render();}
function subscribe(id){stream?.close();clearTimeout(reconnectTimer);connectionState='connecting';stream=new EventSource(`/api/runs/${encodeURIComponent(id)}/events`);stream.addEventListener('state',event=>{try{const data=JSON.parse(event.data);connectionState='live';receive(data.run);}catch(error){console.error('Invalid run state',error);}});stream.onopen=()=>{connectionState='live';renderHud();};stream.onerror=()=>{if(!alive())return;connectionState='reconnecting';renderHud();clearTimeout(reconnectTimer);reconnectTimer=setTimeout(async()=>{try{const data=await api(`/api/runs/${encodeURIComponent(id)}`);if(run?.id===id)receive(data.run);}catch{toast('暂时无法同步任务，连接恢复后会自动继续。');}},5000);};}
function showFieldError(id,error){const el=$(id);if(el){el.innerHTML=errorBox(error.message||String(error));el.hidden=false;el.scrollIntoView({block:'nearest'});}else toast(error.message||String(error));}
function captureTaskForm(){const form=$('#task-form');if(!form)return;const id=form.dataset.scenarioId,d=taskDraft(id);for(const f of scenario(id).fields){if(f.type==='file')continue;const control=form.elements.namedItem(f.name);if(control)d[f.name]=f.type==='number'&&control.value!==''?Number(control.value):control.value;}setInputSource(id,inputSource[id]==='example'?'example':'user');}
async function readUpload(file){if(file.size>8*1024*1024)throw new Error('单个文件最大 8 MB，请精简资料后再上传。');const ext=file.name.split('.').pop().toLowerCase();if(!['csv','json','txt','xlsx'].includes(ext))throw new Error('支持 CSV、JSON、TXT、XLSX 文件。');if(ext==='xlsx'){const buffer=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<buffer.length;i+=8192)binary+=String.fromCharCode(...buffer.subarray(i,i+8192));return {name:file.name,base64:btoa(binary)};}return {name:file.name,text:await file.text()};}
async function startTask(form){if(busy)return;captureTaskForm();const id=form.dataset.scenarioId,s=scenario(id),input={...taskDraft(id),example:inputSource[id]==='example',isExample:inputSource[id]==='example',_source:inputSource[id]==='example'?'example':'user'};for(const f of s.fields){const v=input[f.name];if(f.required&&(v==null||v===''||f.type==='file'&&!v))throw new Error(`请提供${f.label}，也可以明确选择「使用示例」。`);}busy=true;renderPanel(true);try{const data=await api('/api/runs','POST',{scenarioId:id,input,agentConfigs:catalog.agents.map(a=>({id:a.id,instructions:config(a.id).instructions,tools:config(a.id).tools}))});closePanel();receive(data.run);subscribe(data.run.id);toast('任务已派发，AI 员工开始执行。');}finally{busy=false;render();}}
async function action(name){if(busy)return;if(name==='check-provider'){busy=true;renderPanel(true);try{const data=await api('/api/provider/check','POST',{});health.provider=data.provider;toast(data.provider.ready?'模型连接成功':data.provider.message||'模型尚未连接');}finally{busy=false;render();}}else if(name==='refresh'){const [h,r]=await Promise.all([api('/api/health'),api('/api/runs')]);health=h;runs=r.runs||[];if(run){const found=runs.find(x=>x.id===run.id);if(found)receive(found,{initial:true});}render();toast('状态已更新');}else if(name==='cancel'){if(!alive())return;busy=true;try{const data=await api(`/api/runs/${encodeURIComponent(run.id)}/cancel`,'POST',{});receive(data.run);openPanel('progress');}finally{busy=false;render();}}else if(name==='retry'){if(!run||alive())return;busy=true;try{const data=await api(`/api/runs/${encodeURIComponent(run.id)}/retry`,'POST',{});closePanel();receive(data.run);subscribe(data.run.id);}finally{busy=false;render();}}}
document.addEventListener('click',async event=>{const button=event.target.closest('button,[data-open]');if(!button)return;try{if(button.hasAttribute('data-close'))return closePanel();if(button.dataset.open)return openPanel(button.dataset.open);if(button.dataset.agent)return openPanel('agent',button.dataset.agent,'work');if(button.dataset.agentTab){panel.tab=button.dataset.agentTab;return renderPanel(true);}if(button.dataset.scenario){if(alive())return toast('请先等待当前任务完成，或取消当前任务。');return openPanel('task',button.dataset.scenario);}if(button.hasAttribute('data-finance-template')){button.disabled=true;try{await downloadFinanceTemplate();}finally{button.disabled=false;}return;}if(button.dataset.example){captureTaskForm();const id=button.dataset.example;busy=true;renderPanel(true);try{const data=await api(`/api/examples/${encodeURIComponent(id)}`);drafts[id]=data.input;setInputSource(id,'example');toast('已载入明确标记的示例资料，可修改后派工。');}finally{busy=false;renderPanel(true);}return;}if(button.dataset.clearFile){captureTaskForm();const id=panel.id;delete taskDraft(id)[button.dataset.clearFile];setInputSource(id,'user');return renderPanel(true);}if(button.dataset.action)return await action(button.dataset.action);if(button.dataset.approval){if(busy||!run?.approval)return;const note=$('#approval-note')?.value||'',approvalId=run.approval.id;busy=true;try{const data=await api(`/api/runs/${encodeURIComponent(run.id)}/approval`,'POST',{approved:button.dataset.approval==='true',note,approvalId});closePanel();receive(data.run);if(!TERMINAL.has(data.run.status))subscribe(data.run.id);}catch(error){showFieldError('#approval-error',error);}finally{busy=false;render();}return;}if(button.dataset.run){const data=await api(`/api/runs/${encodeURIComponent(button.dataset.run)}`);receive(data.run,{initial:true});if(!TERMINAL.has(data.run.status))subscribe(data.run.id);else{stream?.close();stream=null;}openPanel('progress');return;}if(button.dataset.dismissNotice){notices.delete(button.dataset.dismissNotice);renderNotices();return;}}catch(error){showFieldError(panel?.type==='connection'?'#connection-error':panel?.type==='task'?'#task-error':'#missing',error);}});
document.addEventListener('submit',async event=>{if(event.target.id==='task-form'){event.preventDefault();try{await startTask(event.target);}catch(error){showFieldError('#task-error',error);}}else if(event.target.id==='agent-form'){event.preventDefault();const form=event.target,id=form.dataset.agentId,instructions=form.elements.instructions.value.trim(),tools=[...form.querySelectorAll('[name="tools"]:checked')].map(el=>el.value);if(!instructions)return showFieldError('#agent-error',new Error('请填写具体职责。'));if(!tools.length)return showFieldError('#agent-error',new Error('至少保留一个工具。'));configs[id]={instructions,tools};try{localStorage.setItem(CONFIG_KEY,JSON.stringify(configs));}catch{toast('配置已应用，但浏览器存储不可用。');}toast(`${agent(id).name}的职责与工具已保存，下次派工生效。`);panel.tab='work';renderPanel(true);}});
document.addEventListener('change',async event=>{const input=event.target;if(input.type==='file'&&input.closest('#task-form')){captureTaskForm();const id=panel.id;try{if(input.files[0]){taskDraft(id)[input.name]=await readUpload(input.files[0]);setInputSource(id,'user');renderPanel(true);}}catch(error){input.value='';showFieldError('#task-error',error);}}else if(input.closest('#task-form')){captureTaskForm();setInputSource(panel.id,inputSource[panel.id]==='example'?'example':'user');}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&panel)closePanel();});
$('#zoom-in').addEventListener('click',()=>scene.zoom(.15));$('#zoom-out').addEventListener('click',()=>scene.zoom(-.15));$('#zoom-fit').addEventListener('click',()=>{$scene.classList.toggle('overview');scene.resetView();});$('#topology-toggle').addEventListener('click',event=>{topology=!topology;scene.setTopology(topology);event.currentTarget.classList.toggle('active',topology);event.currentTarget.setAttribute('aria-pressed',String(topology));});
function renderNotices(){noticeLayer.hidden=!!panel;const capacity=innerWidth<720?1:2;while(notices.size>capacity){const [id,notice]=[...notices.entries()].at(-1);notices.delete(id);noticeQueue.unshift(notice);}while(notices.size<capacity&&noticeQueue.length){const index=noticeQueue.findIndex(n=>!notices.has(n.agentId));if(index<0)break;const next=noticeQueue.splice(index,1)[0];notices.set(next.agentId,next);}noticeLayer.innerHTML=[...notices.values()].map(n=>`<article class="employee-notice" data-notice="${esc(n.agentId)}"><div class="employee-notice-head"><button data-agent="${esc(n.agentId)}">${portrait(n.agentId)}<span><strong>${esc(agent(n.agentId).name)} <small>AI 员工</small></strong><em>${esc(agent(n.agentId).role)}</em></span></button><button class="icon-button" data-dismiss-notice="${esc(n.agentId)}" aria-label="收起${esc(agent(n.agentId).name)}的行动提示">${icon('close')}</button></div><dl><div><dt>任务</dt><dd>${esc(n.task)}</dd></div><div><dt>行动</dt><dd>${esc(short(n.action,220))}</dd></div><div class="notice-result"><dt>结果</dt><dd>${esc(short(n.result,300))}</dd></div></dl></article>`).join('');positionOverlays();}
let noticeTick=performance.now();setInterval(()=>{const now=performance.now(),elapsed=now-noticeTick;noticeTick=now;if(panel)return;let changed=false;for(const [id,n]of notices){n.remaining-=elapsed;if(n.remaining<=0){notices.delete(id);changed=true;}}if(changed)renderNotices();},500);
window.addEventListener('resize',()=>{renderNotices();positionOverlays();});
async function boot(){renderHud();renderDock();try{const results=await Promise.allSettled([api('/api/catalog'),api('/api/health'),api('/api/runs')]);if(results[0].status!=='fulfilled')throw results[0].reason;catalog=results[0].value;try{const saved=JSON.parse(localStorage.getItem(CONFIG_KEY)||'{}');for(const a of catalog.agents){const c=saved[a.id];if(c&&typeof c.instructions==='string'&&Array.isArray(c.tools))configs[a.id]={instructions:c.instructions,tools:c.tools.filter(t=>a.tools.includes(t))};}}catch{}if(results[1].status==='fulfilled')health=results[1].value;else health.provider={ready:false,message:results[1].reason.message};if(results[2].status==='fulfilled')runs=results[2].value.runs||[];const current=runs.find(r=>!TERMINAL.has(r.status))||runs[0];if(current){receive(current,{initial:true});if(!TERMINAL.has(current.status))subscribe(current.id);}render();}catch(error){health.provider={ready:false,message:error.message};render();openPanel('connection');}}
boot();
